SELECT * FROM (
  SELECT a.*, ROWNUM rn FROM (
    SELECT * FROM EMPLOYEES
    ORDER BY HIRE_DATE DESC
  ) a WHERE ROWNUM <= #{limit}
) WHERE rn > #{offset}

SELECT * FROM EMPLOYEES


    DEPARTMENT_ID = #{departmentId}


    AND JOB_ID = #{jobId}


    AND SALARY >= #{minSalary}


     AND HIRE_DATE >= TO_DATE(#{hiredAfter}, 'YYYY-MM-DD') 


ORDER BY HIRE_DATE DESC

